def transform(grid):
    # Split by full-width separator; in each half compare the two vertical markers.
    # The output records the color of the right-hand marker in each half.
    sep = next(r for r,row in enumerate(grid) if len(set(row)) == 1 and row[0] != 0)
    tops = grid[:sep]
    bottoms = grid[sep+1:]
    def marker_color(block, col):
        return next((row[col] for row in block if row[col] != 0), 0)
    # output is 2x2, encoding colors at the two marked columns for top and bottom sections
    return [[marker_color(tops, 2), marker_color(tops, 6)],
            [marker_color(bottoms, 2), marker_color(bottoms, 6)]]

